"""Generate the complete, dependency-free bilingual Latitude Samui V5 website.
Run python3 v5/build.py. Authored assets are already included in assets/.
"""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parent
LANG = 'fr'
def t(fr, en): return en if LANG == 'en' else fr
def asset(name): return ('../' if LANG == 'en' else '') + 'assets/' + name
def route(name): return name + '.html'
def image(name, alt, cls='', eager=False):
    return f'<img src="{asset(name)}" alt="{escape(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
ARROW = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 12h15M13 5l7 7-7 7"/></svg>'
def link(label, target, cls='text-link'):
    return f'<a class="{cls}" href="{target}">{label}{ARROW}</a>'
def contact(label=None, intent='contact', villa='', cls='btn', source=''):
    return f'<button class="{cls}" type="button" data-contact="{intent}" data-villa="{escape(villa)}" data-source="{escape(source)}">{label or t("Parlons de votre projet", "Let’s talk about your project")}{ARROW}</button>'
def heading(eyebrow, title, body='', cls=''):
    return f'<div class="section-heading {cls}"><div><p class="eyebrow">{eyebrow}</p><h2>{title}</h2></div>'+ (f'<p class="section-lead">{body}</p>' if body else '')+'</div>'
def photo_note(): return f'<p class="photo-note">{t("Visuels de présentation non contractuels.", "Presentation images are non-contractual.")}</p>'

VILLAS = [
 dict(slug='baansawan', name='Baan Sawan', beds=5, area=252, land=604, price=805000, fr_place='Lamai Heights · Vue mer panoramique', en_place='Lamai Heights · Panoramic sea view', fr_line='La mer, à perte de vue.', en_line='An endless sea horizon.', fr_desc='Sur les hauteurs de Lamai, une villa de cinq chambres ouverte sur le golfe. Des volumes généreux, une piscine privée et la mer pour horizon.', en_desc='Above Lamai, a five-bedroom villa overlooking the gulf. Generous spaces, a private pool and the sea on the horizon.', fr_spirit='Recevoir ses proches, ouvrir les baies et laisser entrer la lumière. Baan Sawan réunit les espaces et l’intimité d’une grande maison, dans un cadre ouvert sur la côte de Samui.', en_spirit='Welcome friends, open the doors and let the light in. Baan Sawan brings together the space and privacy of a generous home with views over Samui’s coastline.', fr_orientation='Vue mer panoramique', en_orientation='Panoramic sea view', delivery=''),
 dict(slug='sabai', name='Villa Sabai', beds=3, area=148, land=445, price=510000, fr_place='Lamai · Orientation sud', en_place='Lamai · South-facing', fr_line='L’art de se sentir chez soi.', en_line='The art of feeling at home.', fr_desc='Trois chambres, une piscine privée et un jardin orienté plein sud. Sabai trouve son équilibre dans une vie ouverte sur l’extérieur.', en_desc='Three bedrooms, a private pool and a south-facing garden. Sabai finds its balance in a life that flows naturally outdoors.', fr_spirit='« Sabai » évoque le confort et la sérénité. Une maison à taille humaine, conçue pour le quotidien comme pour les séjours sur l’île. Le jardin et la terrasse prolongent les pièces de vie, du petit-déjeuner aux soirées tropicales.', en_spirit='“Sabai” evokes comfort and serenity. A home on a human scale, designed for daily life or stays on the island. The garden and terrace extend the living spaces, from breakfast to warm tropical evenings.', fr_orientation='Plein sud', en_orientation='South-facing', delivery='Q4 2028'),
 dict(slug='suk', name='Villa Suk', beds=3, area=152, land=458, price=510000, fr_place='Lamai · Orientation est', en_place='Lamai · East-facing', fr_line='Les matins vous appartiennent.', en_line='Make the mornings yours.', fr_desc='Une villa de trois chambres tournée vers la première lumière du jour. La terrasse, le jardin et la piscine donnent le rythme.', en_desc='A three-bedroom villa facing the first light of day. The terrace, garden and pool set the pace.', fr_spirit='Un café sur la terrasse, les premières lueurs dans le séjour et une journée qui commence sans se presser. Orientée à l’est, Suk privilégie une relation simple entre la maison, le soleil et le jardin.', en_spirit='Coffee on the terrace, the first light in the living room and a day that begins without a rush. Facing east, Suk celebrates a simple relationship between home, sunshine and garden.', fr_orientation='Plein est', en_orientation='East-facing', delivery=''),
 dict(slug='jai', name='Villa Jai', beds=3, area=146, land=450, price=510000, fr_place='Lamai · Orientation ouest', en_place='Lamai · West-facing', fr_line='Prolonger les belles journées.', en_line='Let the good days linger.', fr_desc='Trois chambres et une ouverture plein ouest, pour profiter de la lumière de fin de journée et des longues soirées au bord de la piscine.', en_desc='Three bedrooms and a west-facing setting to enjoy the late afternoon light and long evenings by the pool.', fr_spirit='Jai se vit autant dedans que dehors. Les espaces communs s’ouvrent sur la terrasse, tandis que les chambres préservent leur intimité. Une villa pour se retrouver et prendre le temps.', en_spirit='Jai is lived as much outdoors as indoors. Shared spaces open onto the terrace while the bedrooms retain their privacy. A villa for coming together and taking your time.', fr_orientation='Plein ouest', en_orientation='West-facing', delivery='')
]
def field(v, name): return v[LANG+'_'+name]
def price(v): return f'{v["price"]:,}'.replace(',', ' ')+' €' if LANG=='fr' else '€'+f'{v["price"]:,}'
def villa_card(v, large=False):
    return f'''<a class="villa-card {'large' if large else ''}" href="villa-{v['slug']}.html">
      <div class="card-image">{image(v['slug']+'.webp', v['name'])}<span class="pill">{t('Villa signature' if v['beds']==5 else 'Villa premium','Signature villa' if v['beds']==5 else 'Premium villa')}</span><span class="round-arrow">{ARROW}</span></div>
      <div class="card-info"><div><p class="eyebrow">{field(v,'place')}</p><h3>{v['name']}</h3><p class="card-specs">{v['beds']} {t('chambres','bedrooms')} <span>·</span> {v['area']} m² <span>·</span> {t('Terrain','Plot')} {v['land']} m²</p></div><p class="card-price"><small>{t('À partir de','From')}</small>{price(v)}<sup>*</sup></p></div></a>'''

NAV = [('villas','Les villas','The villas'),('notre-approche','Notre approche','Our approach'),('koh-samui','Koh Samui','Koh Samui'),('equipe',"L’équipe",'The team')]
MORE = [('parcours',"Le parcours d’achat",'Your buying journey'),('faq','Vos questions','Your questions'),('boutique','La boutique','The boutique')]
def nav(page):
    links=''.join(f'<a href="{route(p)}" '+('aria-current="page"' if p==page else '')+f'>{t(fr,en)}</a>' for p,fr,en in NAV)
    more=''.join(f'<a href="{route(p)}">{t(fr,en)}</a>' for p,fr,en in MORE)
    switch = ('../' if LANG=='en' else 'en/')+page+'.html'
    return f'''<a class="skip-link" href="#main">{t('Aller au contenu','Skip to content')}</a><header class="site-header" id="header">
    <a class="brand" href="index.html" aria-label="Latitude Samui — {t('accueil','home')}">{image('logo.svg','Latitude Samui — Villas & Lifestyle',eager=False)}</a>
    <nav class="primary-nav" id="navigation" aria-label="{t('Navigation principale','Main navigation')}">{links}<details class="more-nav"><summary>{t('Découvrir','Explore')}<span aria-hidden="true">+</span></summary><div>{more}</div></details><a class="mobile-contact" href="contact.html">{t('Nous contacter','Contact us')}</a></nav>
    <div class="nav-actions"><a class="language" data-language="{'fr' if LANG=='en' else 'en'}" href="{switch}" lang="{'fr' if LANG=='en' else 'en'}" aria-label="{'Passer en français' if LANG=='en' else 'Switch to English'}">{'FR' if LANG=='en' else 'EN'}</a><a class="nav-contact" href="contact.html">{t('Parlons de votre projet','Let’s talk')}</a><button class="menu-toggle" type="button" aria-controls="navigation" aria-expanded="false" aria-label="{t('Ouvrir le menu','Open menu')}"><span></span><span></span></button></div></header>'''
def footer():
    all_links=''.join(f'<a href="{route(p)}">{t(fr,en)}</a>' for p,fr,en in NAV+MORE)
    return f'''<footer class="site-footer"><div class="footer-top"><div><a class="brand" href="index.html">{image('logo.svg','Latitude Samui — Villas & Lifestyle')}</a><p>{t('Des villas d’architecte.<br>Une autre idée de la vie à Samui.','Architect-designed villas.<br>A different way of life in Samui.')}</p></div><nav aria-label="{t('Navigation de pied de page','Footer navigation')}">{all_links}<a href="contact.html">{t('Nous contacter','Contact us')}</a></nav><div class="footer-contact"><p class="eyebrow">Koh Samui · {t('Thaïlande','Thailand')}</p><p>Bophut</p><a href="mailto:contact@latitudesamui.com">contact@latitudesamui.com</a></div></div><div class="footer-bottom"><span>© 2026 Latitude Samui</span><a href="confidentialite.html">{t('Confidentialité','Privacy')}</a><a href="#top">{t('Retour en haut','Back to top')} ↑</a></div></footer>'''
def cta(title=None, body=None):
    return f'''<section class="closing"><div class="closing-photo">{image('beach.webp',t('Plage bordée de palmiers à Koh Samui','Palm-lined beach in Koh Samui'))}</div><div class="closing-content"><p class="eyebrow">{t('Et si tout commençait ici ?','What if it all began here?')}</p><h2>{title or t('Votre île<br>vous <em>attend.</em>','Your island<br>is <em>waiting.</em>')}</h2><p>{body or t('Un lieu de vie, une résidence secondaire ou un nouveau chapitre. Parlons de ce qui vous amène à Samui.','A home, a place to escape or a new chapter. Let’s talk about what brings you to Samui.')}</p>{contact(cls='btn btn-light')}</div></section>'''
def pagehero(eyebrow,title,body,photo=None):
    return f'<section class="page-hero {"with-photo" if photo else "text-hero"}">'+(image(photo,'',eager=True) if photo else '')+f'<div class="page-hero-content"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="hero-lead">{body}</p></div></section>'
def price_note():
    return f'<p class="fine-print">{t("* Prix de départ en configuration Carte Blanche : villa équipée, non meublée. Mobilier, décoration et aménagements paysagers complémentaires en option. Disponibilité, calendrier et conditions détaillés sur demande.", "* Starting prices for the Carte Blanche specification: equipped, unfurnished villa. Furniture, decoration and additional landscaping are optional. Availability, timelines and detailed terms on request.")}</p>'
def home():
    slides=''.join(f'<div class="hero-slide {"active" if i==0 else ""}">{image(p,"",eager=i==0)}</div>' for i,p in enumerate(['hero.webp','hero-pool.webp','hero-evening.webp']))
    controls=''.join(f'<button type="button" data-slide="{i}" class="slide-dot {"active" if i==0 else ""}" aria-label="{t("Afficher l’image","Show image")} {i+1}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span></button>' for i in range(3))
    return f'''<section class="home-hero" aria-label="Latitude Samui">{slides}<div class="hero-veil"></div><div class="home-hero-content"><p class="eyebrow">Koh Samui, {t('Thaïlande','Thailand')} · Villas & Lifestyle</p><h1>{t('Une île.<br>Votre villa.<br><em>Une autre vie.</em>','An island.<br>Your villa.<br><em>A different life.</em>')}</h1><p class="hero-lead">{t('Des villas d’architecte, pensées entre matière, lumière tropicale et horizons marins.','Architect-designed villas, shaped by natural materials, tropical light and sea horizons.')}</p><div class="hero-actions">{link(t('Découvrir les villas','Explore the villas'),'villas.html','btn btn-light')}{contact(t('Recevoir la brochure','Request the brochure'),'brochure',cls='text-link on-dark',source='home-hero')}</div></div><div class="hero-bottom"><a class="scroll-cue" href="#philosophie">{t('L’esprit Latitude','The Latitude spirit')} <span>↓</span></a><div class="slideshow-controls">{controls}<button type="button" class="slideshow-pause" aria-pressed="false" aria-label="{t('Mettre en pause','Pause slideshow')}">Ⅱ</button></div></div></section>
    <section class="section intro-section" id="philosophie"><div class="intro-title"><p class="eyebrow">{t('Latitude Samui · Notre conviction','Latitude Samui · Our belief')}</p><h2>{t('Le luxe de vivre<br><em>à sa latitude.</em>','The luxury of living<br><em>at your own latitude.</em>')}</h2></div><div class="intro-copy"><p class="large-copy">{t('Une maison qui respire. Un horizon qui apaise. Une équipe qui connaît l’île.','A home with room to breathe. A calming horizon. A team that knows the island.')}</p><p>{t('Nous développons une collection de villas à Koh Samui avec une conviction : l’exigence architecturale et le confort haut de gamme peuvent rester accessibles. Pour y parvenir, nous suivons chaque projet de la conception à la livraison.','We develop a collection of villas in Koh Samui around a simple belief: architectural care and exceptional comfort can remain accessible. To make this possible, we follow each project from design to delivery.')}</p>{link(t('Découvrir notre approche','Discover our approach'),'notre-approche.html')}</div></section>
    <section class="section collection-home" id="villas">{heading(t('La collection','The collection'),t('Des lieux de vie.<br><em>Pas seulement des villas.</em>','Places to live.<br><em>More than villas.</em>'),t('De l’intimité d’un jardin tropical au panorama des hauteurs de Lamai. À chaque villa, sa façon d’habiter l’île.','From an intimate tropical garden to sweeping views above Lamai. Each villa offers its own way of living on the island.'))}<div class="home-villa-grid">{villa_card(VILLAS[0],True)}{villa_card(VILLAS[1])}{villa_card(VILLAS[2])}</div><div class="section-bottom">{price_note()}{link(t('Voir toute la collection','View the full collection'),'villas.html')}</div></section>
    <section class="island-band">{image('island.webp','Koh Samui')}<div><p class="eyebrow">{t('Une île, mille quotidiens','One island, many ways of life')}</p><h2>{t('Ici, le temps<br>prend une <em>autre dimension.</em>','Here, time takes on<br>a <em>different meaning.</em>')}</h2><p>{t('Les marchés du matin. Les baignades improvisées. Une table face à la mer. Le plaisir d’une vie simple, avec le confort à portée de main.','Morning markets. Spontaneous swims. A table by the sea. The pleasure of a simpler life, with everyday comforts close at hand.')}</p>{link(t('Vivre à Koh Samui','Life in Koh Samui'),'koh-samui.html','text-link on-dark')}</div></section>
    <section class="section">{heading(t('Une villa, votre univers','One villa, your world'),t('L’architecture est signée.<br><em>L’atmosphère est la vôtre.</em>','The architecture is ours.<br><em>The atmosphere is yours.</em>'))}{collections_intro()}{link(t('Explorer les trois collections','Explore the three collections'),'notre-approche.html#collections')}</section>
    <section class="team-teaser section dark-section"><div>{heading(t('Des visages derrière chaque projet','The people behind each project'),t('Trois expertises.<br><em>Un engagement commun.</em>','Three areas of expertise.<br><em>One shared commitment.</em>'))}<p class="section-lead">{t('Sébastien, Laurent et Benoît réunissent stratégie, construction et digital. Une organisation directe, au plus près du projet et de son futur propriétaire.','Sébastien, Laurent and Benoît bring together strategy, construction and digital expertise. A direct approach, close to each project and its future owner.')}</p>{link(t('Rencontrer l’équipe','Meet the team'),'equipe.html','text-link on-dark')}</div><div class="team-names"><p><span>01</span>Sébastien<small>{t('Direction & stratégie','Leadership & strategy')}</small></p><p><span>02</span>Laurent<small>{t('Construction & terrain','Construction & operations')}</small></p><p><span>03</span>Benoît<small>{t('Digital & finance','Digital & finance')}</small></p></div></section>
    <section class="section">{heading(t('Le parcours Latitude','The Latitude journey'),t('Du premier échange<br><em>à votre premier matin.</em>','From our first conversation<br><em>to your first morning.</em>'),t('Cinq étapes pour avancer avec une vision claire, du choix de la villa à la remise des clés.','Five steps to move forward with clarity, from choosing your villa to receiving the keys.'))}{steps_compact()}{link(t('Comprendre le parcours d’achat','Understand the buying journey'),'parcours.html')}</section>{cta()}'''

COLLECTIONS = [
 ('Carte Blanche','interieur-carte-blanche.webp',('Villa équipée, non meublée','Equipped, unfurnished villa'),('Une base aboutie : cuisine, salles d’eau et équipements installés. À vous d’y apporter votre mobilier et votre personnalité.','A complete foundation: fitted kitchen, bathrooms and essential equipment. Bring your own furniture and personality.')),
 ('Éveil des Sens','interieur-eveil-des-sens.webp',('Meublée et prête à vivre','Furnished and ready to live in'),('Mobilier principal, luminaires et textiles coordonnés. L’essentiel pour poser vos valises.','Key furniture, lighting and coordinated textiles. The essentials to settle straight in.')),
 ('Art de Vivre','interieur-art-de-vivre.webp',('Un intérieur signature','A signature interior'),('Une composition plus complète, enrichie d’art mural, d’objets, de végétaux et d’équipements de confort.','A more complete composition, enriched with wall art, objects, plants and comfort features.'))
]
def collections_intro():
    return '<div class="collection-grid">'+''.join(f'<article class="collection-card">{image(pic,name)}<div><p class="eyebrow">0{i+1} · {t("Incluse" if i==0 else "En option","Included" if i==0 else "Optional")}</p><h3>{name}</h3><p>{t(*sub)}</p></div></article>' for i,(name,pic,sub,desc) in enumerate(COLLECTIONS))+'</div>'
STEPS = [('Premier échange','First conversation','Votre projet, votre rythme.','Your project, your pace.'),('Visite du projet','Visit the project','Sur place ou à distance.','In person or remotely.'),('Cadre juridique','Legal framework','Comprendre avant de signer.','Understand before signing.'),('Construction suivie','Construction follow-up','Des décisions documentées.','Documented decisions.'),('Remise des clés','Receiving the keys','Commencer votre vie sur l’île.','Start your life on the island.')]
def steps_compact():
    return '<ol class="steps-compact">'+''.join(f'<li><span class="step-number">0{i+1}</span><h3>{t(fr,en)}</h3><p>{t(dfr,den)}</p></li>' for i,(fr,en,dfr,den) in enumerate(STEPS))+'</ol>'
def villas():
    return pagehero(t('La collection Latitude','The Latitude collection'),t('Trouvez votre<br><em>point d’ancrage.</em>','Find your<br><em>place to belong.</em>'),t('Des villas de trois à cinq chambres, chacune avec son orientation, son jardin et son caractère. Un même soin apporté à la façon d’y vivre.','Three- to five-bedroom villas, each with its own setting, garden and character. The same care for how it feels to live there.'))+f'''<section class="section listing-section"><div class="listing-grid">{''.join(villa_card(v) for v in VILLAS)}</div>{price_note()}</section>{village_teaser()}{cta()}'''
def village_teaser():
    return f'<section class="village-teaser"><div>{image("thongkrut.webp","Thong Krut Village")}</div><div class="village-copy"><p class="eyebrow">{t("Bientôt · Le sud de l’île","Coming soon · Southern Samui")}</p><h2>Thong Krut<br><em>Village.</em></h2><p>{t("Un projet de village résidentiel, une écriture architecturale commune et une autre façon de s’installer à Samui. Découvrez l’esprit du programme et échangeons sur les prochaines étapes.","A residential village project, a shared architectural language and another way to make Samui home. Discover the spirit of the development and discuss the next steps.")}</p>{link(t("Découvrir le programme","Explore the development"),"thong-krut-village.html")}</div></section>'
def config(v):
    inner=''
    garden=[('Carte Blanche','jardin-carte-blanche.webp',('Terrain nivelé et engazonné','Levelled and turfed plot'),('Le terrain préparé, la terrasse et la piscine constituent la base de votre extérieur.','The prepared plot, terrace and pool form the foundation of your outdoor spaces.')),('Éclosion','jardin-eclosion.webp',('Le jardin prend vie','The garden comes to life'),('Essences tropicales, plantations, massifs et cheminements structurent les espaces autour de la maison.','Tropical plants, planting beds and paths shape the spaces around your home.')),('Art de Vivre','jardin-art-de-vivre.webp',('Des extérieurs signature','Signature outdoor spaces'),('Une composition plus généreuse avec éclairage paysager et cuisine d’été selon le projet.','A more generous composition with landscape lighting and an outdoor kitchen according to the project.'))]
    for group,opts,label in [('interior',COLLECTIONS,t('01 · L’intérieur','01 · Interiors')),('garden',garden,t('02 · Le jardin','02 · The garden'))]:
        cards=''
        for i,(name,pic,sub,desc) in enumerate(opts):
            cards+=f'<div class="config-option"><label><input type="radio" name="{group}" value="{name}" {"checked" if i==0 else ""}><span class="config-option-body">{image(pic,name)}<span class="config-option-copy"><span class="eyebrow">{t("Incluse" if i==0 else "Sur devis","Included" if i==0 else "On quotation")}<span class="radio-mark"></span></span><strong>{name}</strong><span>{t(*sub)}</span></span></span></label><details><summary>{t("Voir le détail","View details")}</summary><p>{t(*desc)}</p></details></div>'
        inner+=f'<fieldset><legend>{label}</legend><div class="config-grid">{cards}</div></fieldset>'
    return f'''<section class="section config-section dark-section" id="personnalisation" data-config-villa="{v['name']}">{heading(t('Votre configuration','Your configuration'),t('Faites-en<br><em>votre maison.</em>','Make it<br><em>your home.</em>'),t('Choisissez une collection pour l’intérieur, puis une approche pour le jardin. Nous chiffrerons ensemble votre configuration.','Choose an interior collection, then an approach for the garden. We will prepare a quotation for your choices.'))}{inner}<div class="config-summary"><div aria-live="polite"><span class="eyebrow">{t('Votre sélection','Your selection')}</span><p><span data-summary="interior">Carte Blanche</span> <span aria-hidden="true">/</span> <span data-summary="garden">Carte Blanche</span></p><small>{t('Options chiffrées sur devis, en complément du prix de la villa.','Options quoted separately, in addition to the villa price.')}</small></div>{contact(t('Recevoir mon estimation','Request my estimate'),'estimate',v['name'],'btn btn-light','configuration')}</div></section>'''
def villa(v):
    gallery=''.join(f'<button type="button" class="gallery-item" data-gallery="{asset(v["slug"]+"-"+str(i)+".webp")}" data-caption="{v["name"]} · {t("Vue de présentation","Presentation view")} {i}">{image(v["slug"]+"-"+str(i)+".webp",v["name"]+" — "+t("vue de présentation ","presentation view ")+str(i))}<span>0{i} <span aria-hidden="true">↗</span></span></button>' for i in range(1,5))
    facts=[(str(v['beds']),t('Chambres','Bedrooms')),(str(v['beds']),t('Salles d’eau','Bathrooms')),(str(v['area'])+' m²',t('Habitables','Living area')),(str(v['land'])+' m²',t('Parcelle','Plot')),(t('T4 2028','Q4 2028') if v['delivery'] else '12–18 '+t('mois','months'),t('Livraison estimée','Estimated delivery') if v['delivery'] else t('Construction indicative','Indicative construction'))]
    features=[('Piscine privée','Private pool','Une piscine à débordement, équipée pour profiter de l’extérieur au quotidien.','An equipped infinity pool to enjoy outdoor life every day.'),('Cuisine équipée','Fitted kitchen','Une cuisine ouverte sur le séjour, avec électroménager intégré.','A kitchen opening onto the living room, with integrated appliances.'),('Confort tropical','Tropical comfort','Climatisation par zone, toiture isolée et grandes ouvertures sur l’extérieur.','Zoned air conditioning, insulated roofing and generous openings to the outdoors.'),('Finitions au choix','Your choice of finishes','Trois collections d’intérieur et trois approches paysagères.','Three interior collections and three landscaping approaches.')]
    name=v['name'].replace('Villa ','Villa<br><em>')+'</em>' if 'Villa ' in v['name'] else 'Baan<br><em>Sawan.</em>'
    return f'''<section class="villa-hero">{image(v['slug']+'.webp',v['name'],eager=True)}<div class="villa-hero-content"><div><p class="eyebrow">{field(v,'place')}</p><h1>{name}</h1><p class="hero-lead">{field(v,'desc')}</p><div class="hero-actions">{link(t('Personnaliser la villa','Personalise your villa'),'#personnalisation','btn btn-light')}{contact(t('Recevoir la brochure','Request the brochure'),'brochure',v['name'],'text-link on-dark','villa-hero')}</div></div><div class="hero-price"><small>{t('À partir de','From')}</small><p>{price(v)}<sup>*</sup></p><span>Carte Blanche</span></div></div></section>
    <section class="facts-bar" aria-label="{t('Caractéristiques','Key facts')}">{''.join(f'<div><strong>{val}</strong><span>{label}</span></div>' for val,label in facts)}</section>
    <section class="section">{heading(t('L’esprit de la villa','The spirit of the villa'),field(v,'line'),field(v,'spirit'))}<div class="gallery-grid">{gallery}</div><div class="gallery-bottom">{photo_note()}{contact(t('Demander les plans et la brochure','Request floor plans and brochure'),'brochure',v['name'],'text-link','villa-gallery')}</div></section>
    <section class="section features-section">{heading(t('L’essentiel est déjà là','The essentials are already here'),t('Bien pensée.<br><em>Bien équipée.</em>','Thoughtfully designed.<br><em>Fully equipped.</em>'))}<div class="features-grid">{''.join(f'<article><span class="eyebrow">0{i+1}</span><h3>{t(fr,en)}</h3><p>{t(dfr,den)}</p></article>' for i,(fr,en,dfr,den) in enumerate(features))}</div>{price_note()}</section>
    {config(v)}<section class="section location-section"><div><p class="eyebrow">{t('La situation','The location')}</p><h2>{t('Lamai.<br><em>Entre mer et vie locale.</em>','Lamai.<br><em>Between sea and island life.</em>')}</h2><p>{t('Plage, marchés, restaurants et quartiers résidentiels : Lamai offre plusieurs façons de vivre le sud-est de Samui. Lors de la visite, nous vous présentons la parcelle, son accès et son environnement.','Beach, markets, restaurants and residential neighbourhoods: Lamai offers many ways to enjoy south-eastern Samui. During your visit, we introduce the plot, its access and its surroundings.')}</p><div class="location-detail"><span>{t('Environnement','Setting')}</span><strong>{field(v,'orientation')}</strong></div><a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=Lamai+Koh+Samui">{t('Situer Lamai sur la carte','Find Lamai on the map')}{ARROW}</a></div><div class="location-photo">{image('island.webp','Koh Samui')}</div></section>
    <section class="villa-visit dark-section"><p class="eyebrow">{t('Sur place ou en vidéo','In person or by video')}</p><h2>{t('Découvrons','Let’s explore')}<br><em>{v['name']}.</em></h2><p>{t('Une visite personnalisée pour prendre le temps de regarder, de comprendre et de poser vos questions.','A personalised visit with time to look around, understand the project and ask your questions.')}</p>{contact(t('Organiser une visite','Arrange a visit'),'visit',v['name'],'btn btn-light','villa-visit')}</section><section class="section related"><p class="eyebrow">{t('Une autre façon de vivre Samui','Another way to live in Samui')}</p>{villa_card(next(x for x in VILLAS if x['slug']!=v['slug']))}</section>'''

