def dialogs():
    return f'''<dialog id="contact-dialog" class="contact-dialog" aria-labelledby="contact-title"><button class="dialog-close" type="button" data-close aria-label="{t('Fermer','Close')}">×</button><div class="contact-dialog-inner"><p class="eyebrow" id="contact-context">Latitude Samui</p><h2 id="contact-title">{t('Parlons de<br><em>votre projet.</em>','Let’s talk about<br><em>your project.</em>')}</h2><p id="contact-description">{t('Quelques mots pour préparer notre premier échange.','A few details to prepare our first conversation.')}</p><form id="contact-form" novalidate><input type="hidden" name="intent" value="contact"><input type="hidden" name="villa"><input type="hidden" name="source"><div class="form-step" data-step="1"><fieldset class="project-stage"><legend>{t('Où en êtes-vous ?','Where are you in your project?')}</legend><label><input type="radio" name="stage" value="{t('Exploration','Exploring')}" checked>{t('Je découvre les possibilités','I’m exploring the possibilities')}</label><label><input type="radio" name="stage" value="{t('Recherche active','Actively looking')}">{t('Je cherche activement','I’m actively looking')}</label><label><input type="radio" name="stage" value="{t('Prêt à acheter','Ready to buy')}">{t('Mon projet est déjà défini','My project is already defined')}</label></fieldset><div id="visit-options" hidden><label for="visit-type">{t('Votre préférence de visite','Your preferred visit')}</label><select id="visit-type" name="visit"><option value="">{t('À définir ensemble','To discuss together')}</option><option value="{t('Sur place','In person')}">{t('Sur place à Koh Samui','In person in Koh Samui')}</option><option value="{t('Vidéo','Video call')}">{t('À distance en vidéo','By video call')}</option></select></div><button class="btn" type="button" data-next>{t('Continuer','Continue')}{ARROW}</button></div><div class="form-step" data-step="2" hidden><div class="form-grid"><label>{t('Votre nom','Your name')}<input name="name" autocomplete="name" required maxlength="120"></label><label>{t('Votre email','Your email')}<input name="email" type="email" autocomplete="email" required maxlength="200"></label></div><label>{t('Téléphone / WhatsApp (facultatif)','Phone / WhatsApp (optional)')}<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>{t('Quelques mots sur votre projet','A few words about your project')}<textarea name="message" rows="4" maxlength="2500"></textarea></label><div class="form-configuration" id="form-configuration" hidden></div><p class="form-privacy">{t('Ces informations servent à répondre à votre demande.','These details are used to respond to your enquiry.')} <a href="confidentialite.html">{t('Confidentialité','Privacy')}</a></p><div class="form-buttons"><button type="button" class="text-link" data-back>{t('Retour','Back')}</button><button class="btn" type="submit" id="contact-submit">{t('Préparer mon email','Prepare my email')}{ARROW}</button></div></div><p id="form-error" class="form-error" role="alert" hidden></p></form><div id="contact-result" hidden><h3>{t('Votre demande est prête.','Your enquiry is ready.')}</h3><p id="contact-result-text"></p><a class="btn" id="email-send" href="mailto:contact@latitudesamui.com">{t('Ouvrir ma messagerie','Open my email app')}{ARROW}</a><button type="button" class="text-link" id="copy-request">{t('Copier ma demande','Copy my enquiry')}</button><p class="copy-status" aria-live="polite"></p><details><summary>{t('Voir le texte de ma demande','View my enquiry text')}</summary><pre id="request-preview"></pre></details></div></div></dialog>
    <dialog class="lightbox" id="lightbox" aria-label="{t('Galerie de photos','Photo gallery')}"><button type="button" class="dialog-close" data-close aria-label="{t('Fermer la galerie','Close gallery')}">×</button><button type="button" class="lightbox-prev" aria-label="{t('Photo précédente','Previous photo')}">‹</button><figure><img id="lightbox-image" alt=""><figcaption aria-live="polite"></figcaption></figure><button type="button" class="lightbox-next" aria-label="{t('Photo suivante','Next photo')}">›</button></dialog>'''
def render(page, title, description, content, hero=True):
    prefix='../' if LANG=='en' else ''
    source_meta=''
    # Preserve the supplied social preview for the homepage and the existing Baan Sawan route.
    if page=='index': source_meta='<meta property="og:image" content="https://latitudesamui.com/photos/index/01.jpg">'
    elif page=='villa-baansawan': source_meta='<meta property="og:image" content="https://latitudesamui.com/photos/baansawan/01-hero.webp">'
    html=f'''<!doctype html><html lang="{LANG}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#16382f"><title>{escape(title)} — Latitude Samui</title><meta name="description" content="{escape(description)}"><meta name="robots" content="noindex, nofollow"><link rel="icon" type="image/svg+xml" href="{asset('favicon.svg')}"><link rel="icon" href="{prefix}favicon.ico"><link rel="apple-touch-icon" href="{asset('apple-touch-icon.png')}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{prefix}css/site.css"><meta property="og:title" content="{escape(title)} — Latitude Samui"><meta property="og:description" content="{escape(description)}">{source_meta}<script defer src="{prefix}js/config.js"></script><script defer src="{prefix}js/site.js"></script><script defer src="{prefix}js/contact.js"></script></head><body id="top" data-page="{page}" class="{'has-photo-hero' if hero else 'has-text-hero'}">{nav(page)}<main id="main">{content}</main>{footer()}{dialogs()}<noscript><p class="noscript-notice">{t('Pour nous contacter, écrivez à','To contact us, email')} <a href="mailto:contact@latitudesamui.com">contact@latitudesamui.com</a>.</p></noscript></body></html>'''
    target=ROOT/('en' if LANG=='en' else '')/route(page);target.parent.mkdir(exist_ok=True);target.write_text(html,encoding='utf-8')

if __name__=='__main__':
    for language in ['fr','en']:
        LANG=language
        render('index',t('Villas & Lifestyle à Koh Samui','Villas & Lifestyle in Koh Samui'),t('Villas de trois à cinq chambres à Lamai. Architecture, finitions personnalisables et accompagnement par une équipe à Koh Samui.','Three- to five-bedroom villas in Lamai. Architecture, personal interiors and guidance from a team in Koh Samui.'),home())
        render('villas',t('Les villas','The villas'),t('Découvrez Baan Sawan, Sabai, Suk et Jai, ainsi que le projet Thong Krut Village.','Discover Baan Sawan, Sabai, Suk and Jai, and the Thong Krut Village project.'),villas(),False)
        for v in VILLAS: render('villa-'+v['slug'],v['name'],field(v,'desc'),villa(v))
        for p,title,desc,content,hero in editorial_pages(globals()):render(p,title,desc,content,hero)
    print('Generated',len(list(ROOT.glob('*.html')))+len(list((ROOT/'en').glob('*.html'))),'HTML pages')
